		&XMLWhenFilterClosing;




select @ma_hd as ma_hd, @vu_viec as vu_viec, @loai_sp as loai_sp
exec rs_paycontract  @ma_hd, @vu_viec, @kieu_xem, @co_dot_tt, @loai_sp, @@unit, '@@sysDatabaseName', @@language, @@userID, @@admin






			&OutlineEntry;
			&JavascriptReportFilter; 
			&ScriptQueryFilterString;

function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	if (f._convection) f._convection = null;
	else {
		changeLookupReadonly(f, 'vu_viec');
		var o = f.getItem('maxLength');
		o.value = o.maxLength;
	}

}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
		var f = e.object, context = e.type.Context, result = e.type.Result;
		switch (context) {
			case 'Checking':
					var g = f.grid;
					g._hiddenForms = [];
					g._alterTitle = [null, [['%s1', f.getItem('ma_hd').value, true]]];
					g._queryFilterString = getQueryFilterString(f, 'ma_hd');

					var kieu_xem = $func.trim(f.getItem('kieu_xem').value);
					if (kieu_xem == '' || kieu_xem == '*') {
							g._hiddenFields = [
									{ Fields: 'ma_hdkt,so_hdkt,ngay_tt_hdkt,ma_dot_hdkt,ty_le_hdkt,tien_hdkt, tien_hdkt1, chenhlech_hdkt,gt_datt_hdkt, han_tt_hdkt', Value: false },
									{ Fields: 'ma_hdcn,so_hdcn,ngay_tt_hdcn,ma_dot_hdcn,ty_le_hdcn,tien_hdcn, tien_hdcn1, chenhlech_hdcn, gt_datt_hdcn, han_tt_hdcn', Value: false }
							];
					} else {
							g._hiddenFields = [
									{ Fields: 'ma_hdkt,so_hdkt,ngay_tt_hdkt,ma_dot_hdkt,ty_le_hdkt,tien_hdkt, tien_hdkt1, chenhlech_hdkt, gt_datt_hdkt, han_tt_hdkt', Value: kieu_xem == '1' },
									{ Fields: 'ma_hdcn,so_hdcn,ngay_tt_hdcn,ma_dot_hdcn,ty_le_hdcn,tien_hdcn, tien_hdcn1, chenhlech_hdcn, gt_datt_hdcn, han_tt_hdcn', Value: kieu_xem == '0' }
							];
					}
					break;
				default:
						break;
		}
}




